before.content:
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$repo = Join-Path $root 'build/stage1-repository'
$temp = Join-Path ([System.IO.Path]::GetTempPath()) ('ji-stage1-consumer-' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path (Join-Path $temp 'src/main/java/fixture') -Force | Out-Null
try {
  & (Join-Path $root 'gradlew.bat') `
    ':ji-agent-api:publishJavaPublicationToStage1Repository' `
    ':ji-agent-core:publishJavaPublicationToStage1Repository' `
    ':ji-extension-api:publishJavaPublicationToStage1Repository' `
    ':ji-ai-api:publishJavaPublicationToStage1Repository' `
    ':ji-session-api:publishJavaPublicationToStage1Repository' `
    ':ji-session-memory:publishJavaPublicationToStage1Repository' `
    ':ji-error-catalog:publishJavaPublicationToStage1Repository' `
    ':ji-test-kit:publishJavaPublicationToStage1Repository'
  if ($LASTEXITCODE -ne 0) { throw "local publication failed: $LASTEXITCODE" }
  @"
pluginManagement { repositories { gradlePluginPortal(); mavenCentral() } }
dependencyResolutionManagement { repositories { maven { url = uri("$($repo.Replace('\','/'))") }; mavenCentral() } }
rootProject.name = "ji-stage1-consumer"
"@ | Set-Content -Encoding utf8 (Join-Path $temp 'settings.gradle.kts')
  @'
plugins { application }

dependencies {
    implementation("io.github.diodeme.ji:ji-agent-api:0.1.0-SNAPSHOT")
    runtimeOnly("io.github.diodeme.ji:ji-agent-core:0.1.0-SNAPSHOT")
    implementation("io.github.diodeme.ji:ji-session-memory:0.1.0-SNAPSHOT")
    implementation("io.github.diodeme.ji:ji-test-kit:0.1.0-SNAPSHOT")
}
application { mainClass.set("fixture.Consumer") }
'@ | Set-Content -Encoding utf8 (Join-Path $temp 'build.gradle.kts')
  @'
package fixture;

import io.github.diodeme.ji.agent.AgentRuntimeBuilder;
import io.github.diodeme.ji.agent.PermissionDecider;
import io.github.diodeme.ji.agent.SessionOptions;
import io.github.diodeme.ji.agent.ToolDefinition;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.ModelStreamEvent;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.session.memory.MemorySessionStore;
import io.github.diodeme.ji.testkit.ScriptedModelProvider;
import java.util.List;
import java.util.Map;

public final class Consumer {
  public static void main(String[] args) {
    var provider = new ScriptedModelProvider()
        .enqueue(List.of(new ScriptedModelProvider.Step.Tool("call-1", "echo", Map.of("value", "hello")),
            new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.TOOL_USE)))
        .enqueue(List.of(new ScriptedModelProvider.Step.Text("done"),
            new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
    try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(new MemorySessionStore())
        .tool(ToolDefinition.sync("echo", "echo", Map.of("type", "object"),
            (input, cancellation) -> ToolDefinition.ToolResult.text(String.valueOf(input.get("value")))))
        .permissionDecider(request -> java.util.concurrent.CompletableFuture.completedFuture(PermissionDecider.Decision.ALLOW))
        .build()) {
      var session = runtime.newSession(new SessionOptions(new ModelRef("faux", "model"), "."));
      session.prompt("go").completion().toCompletableFuture().join();
      if (!session.transcript().stream().map(message -> message.text()).toList().equals(List.of("go", "", "hello", "done"))) {
        throw new IllegalStateException("tool loop transcript mismatch");
      }
      System.out.println("STAGE1_CONSUMER_OK");
    }
  }
}
'@ | Set-Content -Encoding utf8 (Join-Path $temp 'src/main/java/fixture/Consumer.java')
  & (Join-Path $root 'gradlew.bat') --no-daemon -p $temp run
  if ($LASTEXITCODE -ne 0) { throw "consumer failed: $LASTEXITCODE" }
} finally {
  Remove-Item -Recurse -Force $temp -ErrorAction SilentlyContinue
}

